        tz = (rng() - 0.5) * MAP_SIZE * 0.5;
        th = computeH(tx, tz, noise2D, warpNoise, p, maxH, waterH, features);
        if (th / maxH > waterH / maxH + 0.1 && th / maxH < 0.65) {
          found = true;
          break;
        }
